/* Volta Studio — Base Styles */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;500;600;700;800;900&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --accent-warm: #C4A77D;
  --accent-terracotta: #B85C38;
  --accent-sage: #8B9E7D;
  --accent-sand: #D4C4A8;
  --serif: 'Playfair Display', Georgia, serif;
  --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--sans);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5rem 3rem;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: var(--bg);
}

.logo {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.nav {
  display: flex;
  gap: 2.5rem;
}

.nav a {
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  transition: opacity 0.2s;
}

.nav a:hover {
  opacity: 0.6;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 6px;
  cursor: pointer;
  z-index: 200;
  background: none;
  border: none;
  padding: 0.5rem;
}

.hamburger span {
  width: 28px;
  height: 2px;
  background: var(--text);
  transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(6px, 6px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(6px, -6px);
}

/* Mobile Menu Overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: 2.5rem;
  font-weight: 500;
}

/* Page Layout */
.page {
  padding-top: 80px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 3rem;
}

/* Typography */
h1, h2, h3, h4 {
  font-family: var(--serif);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

/* Hero */
.hero {
  padding: 8rem 3rem 4rem;
  max-width: 1000px;
}

.hero h1 {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 800;
}

/* Media Showcase */
.media-showcase {
  padding: 4rem 3rem;
}

.media-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.media-block {
  aspect-ratio: 4/5;
  border-radius: 4px;
}

.media-block:nth-child(1) { background: #C4A77D; }
.media-block:nth-child(2) { background: #8B9E7D; }
.media-block:nth-child(3) { background: #D4C4A8; }

/* Client Marquee */
.client-marquee {
  padding: 3rem 0;
  overflow: hidden;
  border-top: 1px solid rgba(26,26,26,0.1);
  border-bottom: 1px solid rgba(26,26,26,0.1);
}

.marquee-row {
  display: flex;
  gap: 3rem;
  padding: 0.75rem 0;
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 500;
  white-space: nowrap;
}

.marquee-row:nth-child(1) {
  animation: marquee-left 25s linear infinite;
}

.marquee-row:nth-child(2) {
  animation: marquee-right 30s linear infinite;
}

.marquee-row:nth-child(3) {
  animation: marquee-left 28s linear infinite;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-row span::after {
  content: " ◦";
  opacity: 0.4;
}

/* About Section */
.about {
  padding: 6rem 3rem;
  max-width: 800px;
  margin: 0 auto;
}

.about h2 {
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 2rem;
  font-family: var(--sans);
  font-weight: 500;
}

.about p {
  font-size: 1.25rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

.about p:last-child {
  margin-bottom: 0;
}

/* Founder Letter (Neweno) */
.founder-letter {
  padding: 6rem 3rem 8rem;
  max-width: 680px;
  margin: 0 auto;
}

.founder-letter .eyebrow {
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 2rem;
  font-family: var(--sans);
  font-weight: 500;
}

.founder-letter h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 3rem;
  font-weight: 700;
}

.founder-letter p {
  font-size: 1.125rem;
  line-height: 1.9;
  margin-bottom: 1.75rem;
  color: #333;
}

.founder-letter p:last-child {
  margin-bottom: 0;
}

/* Services */
.services-hero {
  padding: 8rem 3rem 4rem;
  max-width: 800px;
}

.services-hero h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 2rem;
}

.services-hero .subtitle {
  font-size: 1.25rem;
  color: #555;
  max-width: 600px;
}

.philosophy {
  padding: 4rem 3rem;
  border-top: 1px solid rgba(26,26,26,0.1);
}

.philosophy h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 2rem;
}

.philosophy p {
  font-size: 1.125rem;
  line-height: 1.9;
  max-width: 650px;
  color: #333;
}

.service-divider {
  padding: 0 3rem;
}

.service-divider .line {
  height: 1px;
  background: rgba(26,26,26,0.1);
}

.service-details {
  padding: 4rem 3rem 8rem;
  max-width: 800px;
}

.service-details h3 {
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  font-family: var(--sans);
  font-weight: 500;
}

.service-item {
  margin-bottom: 4rem;
}

.service-item h4 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  margin-bottom: 1rem;
}

.service-item p {
  font-size: 1.125rem;
  line-height: 1.8;
  color: #444;
}

/* Clients */
.clients-page {
  padding: 8rem 3rem 8rem;
}

.clients-heading {
  margin-bottom: 4rem;
}

.clients-heading h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
}

.clients-heading p {
  margin-top: 1rem;
  font-size: 1.125rem;
  color: #555;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2rem;
}

.client-item h3 {
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
  font-weight: 700;
}

.client-item p {
  font-size: 0.95rem;
  color: #555;
  line-height: 1.6;
}

/* Contact */
.contact-page {
  padding: 8rem 3rem;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.contact-hero h1 {
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 900;
  line-height: 0.9;
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  gap: 2rem;
  font-size: 1.25rem;
}

.contact-links a {
  position: relative;
}

.contact-links a::after {
  content: ".";
}

.contact-links a:hover {
  opacity: 0.6;
}

/* Responsive */
@media (max-width: 900px) {
  .nav {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 6rem 1.5rem 3rem;
  }

  .media-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .media-showcase {
    padding: 2rem 1.5rem;
  }

  .media-block {
    aspect-ratio: 16/9;
  }

  .about {
    padding: 4rem 1.5rem;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 2.5rem 1.5rem;
  }

  .clients-page {
    padding: 6rem 1.5rem 4rem;
  }

  .contact-page {
    padding: 6rem 1.5rem;
  }
}

@media (max-width: 600px) {
  .header {
    padding: 1rem 1.5rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }

  .contact-links {
    flex-direction: column;
    gap: 1rem;
  }
}

