  content: " ◦";
  opacity: 0.4;
}

/* About Section */
.about {
  padding: 6rem 3rem;
  max-width: 800px;
  margin: 0 auto;
}

.about h2 {
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 2rem;
  font-family: var(--sans);
  font-weight: 500;
}

.about p {
  font-size: 1.25rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

.about p:last-child {
  margin-bottom: 0;
}

/* Founder Letter (Neweno) */
.founder-letter {
  padding: 6rem 3rem 8rem;
  max-width: 680px;
  margin: 0 auto;
}

.founder-letter .eyebrow {
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 2rem;
  font-family: var(--sans);
  font-weight: 500;
}

.founder-letter h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 3rem;
  font-weight: 700;
}

.founder-letter p {
  font-size: 1.125rem;
  line-height: 1.9;
  margin-bottom: 1.75rem;
  color: #333;
}

.founder-letter p:last-child {
  margin-bottom: 0;
}

/* Services */
.services-hero {
  padding: 8rem 3rem 4rem;
  max-width: 800px;
}

.services-hero h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 2rem;
}

.services-hero .subtitle {
  font-size: 1.25rem;
  color: #555;
  max-width: 600px;
}

.philosophy {
  padding: 4rem 3rem;
  border-top: 1px solid rgba(26,26,26,0.1);
}

.philosophy h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 2rem;
}

.philosophy p {
  font-size: 1.125rem;
  line-height: 1.9;
  max-width: 650px;
  color: #333;
}

.service-divider {
  padding: 0 3rem;
}

.service-divider .line {
  height: 1px;
  background: rgba(26,26,26,0.1);
}

.service-details {
  padding: 4rem 3rem 8rem;
  max-width: 800px;
}

.service-details h3 {
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  font-family: var(--sans);
  font-weight: 500;
}

.service-item {
  margin-bottom: 4rem;
}

.service-item h4 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  margin-bottom: 1rem;
}

.service-item p {
  font-size: 1.125rem;
  line-height: 1.8;
  color: #444;
}

/* Clients */
.clients-page {
  padding: 8rem 3rem 8rem;
}

.clients-heading {
  margin-bottom: 4rem;
}

.clients-heading h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
}

.clients-heading p {
  margin-top: 1rem;
  font-size: 1.125rem;
  color: #555;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2rem;
}

.client-item h3 {
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
  font-weight: 700;
}

.client-item p {
  font-size: 0.95rem;
  color: #555;
  line-height: 1.6;
}

/* Contact */
.contact-page {
  padding: 8rem 3rem;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.contact-hero h1 {
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 900;
  line-height: 0.9;
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  gap: 2rem;
  font-size: 1.25rem;
}

.contact-links a {
  position: relative;
}

.contact-links a::after {
  content: ".";
}

.contact-links a:hover {
  opacity: 0.6;
}

/* Responsive */
@media (max-width: 900px) {
  .nav {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 6rem 1.5rem 3rem;
  }

  .media-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .media-showcase {
    padding: 2rem 1.5rem;
  }

  .media-block {
    aspect-ratio: 16/9;
  }

  .about {
    padding: 4rem 1.5rem;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 2.5rem 1.5rem;
  }

  .clients-page {
    padding: 6rem 1.5rem 4rem;
  }

  .contact-page {
    padding: 6rem 1.5rem;
  }
}

@media (max-width: 600px) {
  .header {
    padding: 1rem 1.5rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }

  .contact-links {
    flex-direction: column;
    gap: 1rem;
  }
}
